#!/usr/bin/env python3
"""
generate_claude_settings.py — claude-coding-contract-compiler v2.7.0
From a validated contract JSON instance, emit:
  .claude/settings.json   — direct remote-mutation denials for Claude Code
  CLAUDE.md               — scope, resume, one-commit, and terminal-delivery instructions
"""
import argparse, copy, json
from pathlib import Path

SETTINGS_TEMPLATE = {
    "permissions": {
        "deny": [],
        "allow": []
    }
}

CLAUDE_MD_TEMPLATE = """# CLAUDE.md — {contract_id}
<!-- Auto-generated by claude-coding-contract-compiler v2.7.0 -->
<!-- DO NOT EDIT MANUALLY — regenerate from the contract instance -->

## Contract
- **ID**: {contract_id}
- **Target**: `{target_repo}` shared campaign branch `{target_branch}`
- **Prerequisite**: {prerequisite}
- **Fits one session**: {fits_one_session}

## Scope
Implement exactly this slice. Do not expand scope.

### In scope
{in_scope_list}

### Hard out of scope
{hard_oos_list}

### Preserved files
{preserved_list}

## Resume-from
Run the generated `preflight.sh` before editing.
It verifies the shared branch, target-native cold-resume state, and, for contract 2+, the
immediately previous contract's exact local commit plus that predecessor's dedicated completion
proof. It does not replay the predecessor's repository-wide commit gate.

Assumed state:
```
{resume_assumes}
```
If any precondition is false: **{if_assumption_false}**

## Git execution law
- Work only on shared branch `{shared_branch}`.
- This contract creates **exactly one local commit** after every required-before-commit command passes.
- Create the commit with exact command: `{commit_command}`
- Exact subject: `{commit_subject}`
- Do not amend/rewrite the committed predecessor contract.
- Do not push between contracts.
- Direct `git push` and direct PR-creation commands remain denied.
{delivery_rule}

### Required before this contract's one commit
{commit_gate_list}

## Halt boundary
Stop immediately before direct actions in this list unless the terminal `make pr` exception above explicitly applies:
{halt_list}

## Read-only live queries allowed
{read_only_list}

## Done when
{handoff_green}
"""


def _deny_pattern(pattern: str) -> str:
    if pattern.startswith("Bash(") and pattern.endswith(")"):
        pattern = pattern[5:-1]
    if pattern.endswith(":*"):
        pattern = pattern[:-2]
    return pattern


def generate(contract: dict, output_dir: Path) -> None:
    cid = contract["contract_id"]
    repo = contract.get("target_repo", "")
    branch = contract.get("target_branch", "main")
    prereq = contract.get("resume_from", {}).get("assumes_already_green", [])
    halt = contract.get("halt_boundary", [])
    denied = contract.get("execution_authority", {}).get("denied_tools", [])
    ro = contract.get("execution_authority", {}).get("read_only_authority", [])
    in_scope = [d["deliverable"] for d in contract.get("scope_lock", {}).get("in_scope", [])]
    hard_oos = contract.get("scope_lock", {}).get("hard_out_of_scope", [])
    preserved = [(p["path"], p["guarantee"]) for p in contract.get("scope_lock", {}).get("preserved_files", [])]
    resume_if = contract.get("resume_from", {}).get("if_assumption_false", "HALT RESUME_PRECONDITION_NOT_SATISFIED")
    green = contract.get("handoff", {}).get("next_session_may_assume_green", [])
    budget = contract.get("session_budget", {})
    fits = budget.get("fits_one_session", True)
    git = contract.get("git_workflow", {})
    delivery = git.get("terminal_delivery", {})
    gate = contract.get("commit_gate", {}).get("required_before_commit", [])

    settings = copy.deepcopy(SETTINGS_TEMPLATE)
    settings["permissions"]["deny"] = [_deny_pattern(d) for d in denied]
    settings_path = output_dir / cid / ".claude" / "settings.json"
    settings_path.parent.mkdir(parents=True, exist_ok=True)
    settings_path.write_text(json.dumps(settings, indent=2) + "\n")

    def bullet(items):
        return "\n".join(f"- {x}" for x in items) if items else "_(none)_"

    ro_strs = [f"{r['resource']} ({r['method']})" for r in ro] if ro else []
    if delivery.get("authorized"):
        delivery_rule = (
            "- This is the terminal contract. After its one validated local commit exists, run exactly "
            "`make pr` once. That wrapper is the sole authorized push/PR-opening path for the entire chain."
        )
    else:
        delivery_rule = "- This is not the terminal contract. Remote delivery is forbidden; hand off locally to the next contract."

    md = CLAUDE_MD_TEMPLATE.format(
        contract_id=cid,
        target_repo=repo,
        target_branch=branch,
        prerequisite=", ".join(prereq) if prereq else "none",
        fits_one_session=fits,
        in_scope_list=bullet(in_scope),
        hard_oos_list=bullet(hard_oos[:8]) + ("\n- ..." if len(hard_oos) > 8 else ""),
        preserved_list=bullet([f"`{p}` — {g}" for p, g in preserved]),
        resume_assumes="\n".join(prereq) if prereq else "none",
        if_assumption_false=resume_if,
        shared_branch=git.get("shared_branch", branch),
        commit_subject=git.get("commit_subject", cid),
        commit_command=git.get("commit_command", f'git commit -m "{cid}"'),
        delivery_rule=delivery_rule,
        commit_gate_list=bullet([f"`{cmd}`" for cmd in gate]),
        halt_list=bullet(halt) if halt else "_(none)_",
        read_only_list=bullet(ro_strs) if ro_strs else "_(none beyond normal repository read)_",
        handoff_green="\n".join(f"- {g}" for g in green) if green else "_(see contract)_",
    )
    md_path = output_dir / cid / "CLAUDE.md"
    md_path.write_text(md)
    print(f"  {cid}: {settings_path}  {md_path}")


def main():
    ap = argparse.ArgumentParser(description="Emit .claude/settings.json + CLAUDE.md per contract.")
    ap.add_argument("instances", nargs="+", help="Contract JSON instance files")
    ap.add_argument("--output-dir", default=".", help="Root output directory")
    args = ap.parse_args()
    out = Path(args.output_dir)
    for path in args.instances:
        c = json.loads(Path(path).read_text())
        generate(c, out)
    print("Done.")


if __name__ == "__main__":
    main()
